import std.io

pub type AppError = Failed(String)

record Cell { n: Int64 }

pub fn main() effect io -> Result<(), AppError> {
    let cs = [Cell { n: 1 }, Cell { n: 7 }]
    let f = cs.iterator().find(|c| c.n > 5)
    match f {
        Some(c) => { io.println("found ${c.n}") }
        None => { io.println("none") }
    }
    return Ok(())
}
